Our tip-split function sometimes returns negative amounts. Here's the module:

const stripe = require('stripe')('{{secret:stripe}}');

async function splitTips(shift) {
  const pool = shift.cardTips + shift.cashTips;
  const share = pool / shift.staff.length;
  return shift.staff.map(s => ({ id: s.id, amount: share - s.advance }));
}

async function payOut(rows) {
  for (const r of rows) await stripe.transfers.create({ amount: r.amount * 100, currency: 'usd', destination: r.id });
}

